export default function (input) {
  const level = Number(input.amount) >= 100000 ? "部長" : "課長";
  const found = (input.approvers || []).find((r) => r.level === level);
  if (!found) throw new Error("役職「" + level + "」の承認者が見つかりません");
  return { approver: found.name, level: level };
}

